#include "tclOOInt.h"
#include <stdio.h>
#include <stdlib.h>
static void call(Tcl_Interp *ip,int n,Tcl_Obj **v){for(int x=0;x<n;x++)Tcl_IncrRefCount(v[x]);int c=Tcl_EvalObjv(ip,n,v,0);for(int x=0;x<n;x++)Tcl_DecrRefCount(v[x]);if(c!=TCL_OK){fprintf(stderr,"call %s\n",Tcl_GetStringResult(ip));exit(2);}}
static Object *object(Tcl_Interp *ip,const char *name){Tcl_Obj *v=Tcl_NewStringObj(name,-1);Tcl_IncrRefCount(v);Object *o=(Object*)Tcl_GetObjectFromObj(ip,v);Tcl_DecrRefCount(v);return o;}
static Method *method(Class *c,const char *key){Tcl_Obj *v=Tcl_NewStringObj(key,-1);Tcl_IncrRefCount(v);Tcl_HashEntry *e=Tcl_FindHashEntry(&c->classMethods,v);Method *m=e?Tcl_GetHashValue(e):NULL;Tcl_DecrRefCount(v);if(!m){fprintf(stderr,"no method %s\n",key);exit(4);}return m;}
int main(int argc,char **argv){Tcl_FindExecutable(argv[0]);Tcl_Interp*ip=Tcl_CreateInterp();if(Tcl_Init(ip)!=TCL_OK)return 2;if(Tcl_Eval(ip,"oo::configurable create C;C create o")!=TCL_OK)return 3;Object *c=object(ip,"C");const char *names[]={"p","x\xff","x\0tail"};int lengths[]={1,2,6};for(int k=0;k<3;k++){
Tcl_Obj *name=Tcl_NewStringObj(names[k],lengths[k]);Tcl_IncrRefCount(name);Tcl_Obj *v[]={Tcl_NewStringObj("oo::define",-1),Tcl_NewStringObj("C",-1),Tcl_NewStringObj("property",-1),name};call(ip,4,v);char key[40];snprintf(key,sizeof(key),"<ReadProp-%s>",names[k]);Method *reader=method(c->classPtr,key);snprintf(key,sizeof(key),"<WriteProp-%s>",names[k]);Method *writer=method(c->classPtr,key);printf("decl-%d\t%d\t%d\t%d\t%s\n",k,reader->clientData==name,writer->clientData==name,name->refCount,name->typePtr?name->typePtr->name:"none");
char dashed[12];dashed[0]='-';memcpy(dashed+1,names[k],lengths[k]);Tcl_Obj *q=Tcl_NewStringObj(dashed,lengths[k]+1);Tcl_IncrRefCount(q);Tcl_Obj *value=Tcl_NewStringObj("VALUE",-1);Tcl_IncrRefCount(value);Tcl_Obj *write[]={Tcl_NewStringObj("o",-1),Tcl_NewStringObj("configure",-1),q,value};call(ip,4,write);printf("write-%d\t%d\t%s\t%d\n",k,name->refCount,name->typePtr?name->typePtr->name:"none",Tcl_GetCharLength(Tcl_GetObjResult(ip))==0);Tcl_Obj *read[]={Tcl_NewStringObj("o",-1),Tcl_NewStringObj("configure",-1),q};call(ip,3,read);printf("read-%d\t%d\t%s\t%d\t%s\n",k,name->refCount,name->typePtr?name->typePtr->name:"none",Tcl_GetObjResult(ip)==value,q->typePtr?q->typePtr->name:"none");Tcl_DecrRefCount(q);Tcl_DecrRefCount(value);Tcl_DecrRefCount(name);}
Tcl_DeleteInterp(ip);Tcl_Finalize();return 0;}
